def timeline():
    s='<div class="tlf" role="group" aria-label="时间线筛选"><button class="on" data-f="all">全部</button><button data-f="c">耶路撒冷与早期教会</button><button data-f="p">保罗</button><button data-f="w">罗马世界</button></div><ol class="tl">'
    for y,c,t,d in sorted(TL,key=lambda x:x[0]):
        s+=f'<li class="tli c-{c} reveal"><span class="yr">{y}</span><div class="tlc glass"><p>{md(t)}</p>{f"<small>{d}</small>" if d else ""}</div></li>'
    return s+'</ol>'
