def story():
    s='<div class="story">'
    for i,(ic,t,r,d,h) in enumerate(STORY):
        s+=f'<a class="st reveal" href="{h}" style="--i:{i}"><span class="sn">{i+1}</span><span class="sic">{ic}</span><b>{t}</b><small>{r}</small><p>{d}</p></a>'
    return s+'</div>'
